actions.script:
const base = 'component://webroot/screen/webroot/js/vault/'
const sri = (location) => {
    try {
        const hex = String(ec.resource.digest(location, 'sha256') || '')
        if (!/^[0-9a-f]{64}$/.test(hex)) return null
        let latin = ''
        for (let i = 0; i < 64; i += 2) latin += String.fromCharCode(parseInt(hex.substring(i, i + 2), 16))
        return 'sha256-' + btoa(latin)
    } catch (err) {
        ec.logger.warn('Vault: no integrity hash for ' + location + ': ' + err)
        return null
    }
}
const number = (selector, fallback) => {
    const value = Number(ec.factory.getConfValue(selector))
    return Number.isFinite(value) && value >= 0 ? value : fallback
}
const types = ec.entity.find('moqui.security.vault.VaultItemType').orderBy('sequenceNum').disableAuthz().useCache(true).list()
const fields = ec.entity.find('moqui.security.vault.VaultItemTypeField').orderBy('sequenceNum').disableAuthz().useCache(true).list()
const kinds = {VfText: 'text', VfSecret: 'secret', VfUrl: 'url', VfTotp: 'totp', VfMultiLine: 'multi-line', VfDate: 'date', VfFileName: 'file-name'}
const itemTypes = Array.from(types).map((type) => ({id: type.vaultItemTypeId, label: ec.l10n.localize(type.description || type.vaultItemTypeId),
    fields: Array.from(fields).filter((field) => field.vaultItemTypeId === type.vaultItemTypeId).map((field) => ({name: field.fieldName,
        label: ec.l10n.localize(field.label || field.fieldName), kind: kinds[field.fieldKindEnumId] || 'text', masked: field.masked === 'Y'}))}))
ec.web.sendJsonResponse({userId: ec.user.userId, username: ec.user.username, idleMinutes: number('boss/vault@idle-minutes', 15),
    clipboardSeconds: number('boss/vault@clipboard-seconds', 30), itemTypes: itemTypes,
    wasmIntegrity: sri(base + 'moqui_vault.wasm'), workerIntegrity: sri(base + 'VaultWorker.js')})

const text = String(term || '').trim()
const cf = ec.entity.conditionFactory
let find = ec.entity.find('moqui.security.UserAccount').condition('disabled', 'not-equals', 'Y').orderBy('username').limit(50).disableAuthz()
if (text) find = find.condition(cf.makeCondition([cf.makeCondition('username', 'like', '%' + text + '%').ignoreCase(),
    cf.makeCondition('userFullName', 'like', '%' + text + '%').ignoreCase()], 'or'))
const accounts = Array.from(find.list()).filter((account) => account.userId !== ec.user.userId)
const ids = accounts.map((account) => account.userId)
const keyed = new Set(ids.length ? Array.from(ec.entity.find('moqui.security.vault.VaultPersonalKey').condition('userId', 'in', ids)
    .condition('statusId', 'VpkActive').disableAuthz().list()).map((key) => key.userId) : [])
ec.web.sendJsonResponse(accounts.filter((account) => keyed.has(account.userId)).slice(0, 20).map((account) => ({value: account.userId,
    label: (account.userFullName ? account.userFullName + ' (' + account.username + ')' : account.username)})))

const ids = String(userIds || '').split(',').map((id) => id.trim()).filter((id) => id).slice(0, 200)
const names = {}
if (ids.length) for (const account of Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', ids).disableAuthz().list()))
    names[account.userId] = account.userFullName ? account.userFullName + ' (' + account.username + ')' : account.username
ec.web.sendJsonResponse({names: names})
